/// Works on the document. Depends on Tiers 1 and 2 only.
[<RequireQualifiedAccess>]
module GateYardDocuments =

    /// The document before its first write.
    let empty : GateYardDocument =
        { Version = None
          Entries = Map.empty
          Applied = Map.empty }

    /// A session over a document just read.
    let start (document: GateYardDocument) : GateYardDocumentSession =
        { Stored = document; Working = document; Pending = None }

    /// Reads the document and starts a session over it.
    let load (store: IGateYardDocumentStore) : GateYardDocumentLoaded =
        match store.Read() with
        | GateYardDocumentRead.Found document -> GateYardDocumentLoaded.Loaded(start document)
        | GateYardDocumentRead.Missing -> GateYardDocumentLoaded.DocumentMissing(start empty)
        | GateYardDocumentRead.ReadFailed reason -> GateYardDocumentLoaded.LoadFailed reason

    let private withEntry (session: GateYardDocumentSession) (entry: GateYardEntry) =
        { session with Working = { session.Working with Entries = Map.add entry.Id entry session.Working.Entries } }

    /// Adds an entry at the workflow's initial state, in memory. Refused while a save is unknown.
    let create (session: GateYardDocumentSession) (id: GateYardId) : GateYardCreated =
        match session.Pending with
        | Some pending -> GateYardCreated.Unreconciled pending
        | None when Map.containsKey id session.Working.Entries -> GateYardCreated.AlreadyExists id
        | None -> GateYardCreated.Created(withEntry session { Id = id; Revision = 0L; State = GateYardState.Closed })

    /// Decides one command against one entry and applies it to the working copy. `expected`, when
    /// given, is the entry revision the caller acted on. Refused while a save is unknown.
    let apply (rules: GateYardRules) (session: GateYardDocumentSession) (id: GateYardId) (expected: int64 option) (command: GateYardCommand) : GateYardCommandOutcome =
        match session.Pending, Map.tryFind id session.Working.Entries, expected with
        | Some pending, _, _ -> GateYardCommandOutcome.Unreconciled pending
        | None, None, _ -> GateYardCommandOutcome.EntryNotFound id
        | None, Some entry, Some revision when revision <> entry.Revision -> GateYardCommandOutcome.EntryStale(id, revision, entry.Revision)
        | None, Some entry, _ ->
            match GateYardTransition.decide rules entry.State command with
            | Error refusal -> GateYardCommandOutcome.Refused(refusal, entry)
            | Ok decision ->
                GateYardCommandOutcome.Applied(withEntry session { entry with Revision = entry.Revision + 1L; State = decision.Next }, decision)

    let private write (store: IGateYardDocumentStore) (session: GateYardDocumentSession) (operation: GateYardOperationId) =
        match store.Write(operation, session.Stored.Version, session.Working) with
        | GateYardDocumentWrite.Written version ->
            let stored = { session.Working with Version = Some version; Applied = Map.add operation version session.Working.Applied }
            GateYardSaveOutcome.Saved(operation, version), { session with Stored = stored; Working = stored }
        | GateYardDocumentWrite.VersionMismatch current -> GateYardSaveOutcome.SaveConflict current, session
        | GateYardDocumentWrite.WriteFailed error when error.ProvenNotApplied -> GateYardSaveOutcome.NotSaved error.Reason, session
        | GateYardDocumentWrite.WriteFailed _ -> GateYardSaveOutcome.OutcomeUnknown operation, { session with Pending = Some operation }

    /// Writes the working copy under `operation`, expecting the version last read or written. A
    /// failure not proven to be without effect is unknown: it is returned as unknown and blocks
    /// further changes until `reconcile` inspects the stored document.
    let save (store: IGateYardDocumentStore) (session: GateYardDocumentSession) (operation: GateYardOperationId) : GateYardSaveOutcome * GateYardDocumentSession =
        match session.Pending, Map.tryFind operation session.Stored.Applied with
        | Some pending, _ -> GateYardSaveOutcome.Unreconciled pending, session
        | None, Some version -> GateYardSaveOutcome.AlreadySaved(operation, version), session
        | None, None -> write store session operation

    let private inspect (store: IGateYardDocumentStore) (session: GateYardDocumentSession) (operation: GateYardOperationId) =
        let settled = { session with Pending = if session.Pending = Some operation then None else session.Pending }
        match store.Read() with
        | GateYardDocumentRead.ReadFailed reason -> GateYardReconciled.StillUnknown reason, session
        | read ->
            let current = match read with | GateYardDocumentRead.Found document -> document | _ -> empty
            match Map.tryFind operation current.Applied with
            | Some version -> GateYardReconciled.Applied version, { settled with Stored = current; Working = current }
            | None when current.Version = session.Stored.Version -> GateYardReconciled.NotApplied, settled
            | None -> GateYardReconciled.ReconcileConflict current.Version, settled

    /// Inspects the stored document to settle one save whose outcome was unknown. Nothing is written.
    let reconcile (store: IGateYardDocumentStore) (session: GateYardDocumentSession) (operation: GateYardOperationId) : GateYardReconciled * GateYardDocumentSession =
        inspect store session operation

