        | GateYardCommandOutcome.Refused(refusal, _) -> GateYardTransition.refusalCode refusal
        | GateYardCommandOutcome.EntryNotFound _ -> Some GateYardRefusalCode.NoSuchGate
        | GateYardCommandOutcome.EntryStale _ -> Some GateYardRefusalCode.StaleEntry
        | GateYardCommandOutcome.Applied _ | GateYardCommandOutcome.Unreconciled _ -> None

